def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals based on start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current in sorted_intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Merge the intervals
            merged[-1] = (last[0], max(last[1], current[1]))
        else:
            merged.append(current)

    return merged

import re

def parse_duration(text):
    if not text:
        raise ValueError("Empty string")

    total_seconds = 0
    units_seen = set()
    unit_order = ['d', 'h', 'm', 's']

    for part in re.findall(r'(\d+)([dhms])', text):
        number_str, unit = part
        if not number_str.isdigit():
            raise ValueError("Invalid number format")
        number = int(number_str)
        if number < 0:
            raise ValueError("Negative numbers are not allowed")

        if unit not in unit_order:
            raise ValueError("Unknown unit")

        if unit in units_seen:
            raise ValueError("Repeated unit")

        if unit_order.index(unit) < unit_order.index(units_seen.pop()) if units_seen else False:
            raise ValueError("Units must appear in order: d, h, m, s")

        units_seen.add(unit)

        if unit == 'd':
            total_seconds += number * 86400
        elif unit == 'h':
            total_seconds += number * 3600
        elif unit == 'm':
            total_seconds += number * 60
        elif unit == 's':
            total_seconds += number

    if re.search(r'[^\d]', text):
        raise ValueError("Invalid characters in string")

    return total_seconds

