def wrap_text(text, width):
    if not text or not text.strip():
        return []
    words = text.split()
    lines = []
    current_line = []
    current_length = 0
    for word in words:
        if current_length + len(word) + (len(current_line) > 0) <= width:
            current_line.append(word)
            current_length += len(word) + (len(current_line) > 0)
        else:
            lines.append(' '.join(current_line))
            current_line = [word]
            current_length = len(word)
    if current_line:
        lines.append(' '.join(current_line))
    return lines

def compare_versions(a, b):
    def parse_version(version):
        main, _, rest = version.partition('-')
        major, minor, patch = map(int, main.split('.'))
        pre_release = rest.split('+', 1)[0] if '-' in version else ''
        pre_release = pre_release.split('.') if pre_release else []
        return (major, minor, patch, pre_release)

    a_parts = parse_version(a)
    b_parts = parse_version(b)

    # Compare main version numbers
    if a_parts[0] < b_parts[0]:
        return -1
    elif a_parts[0] > b_parts[0]:
        return 1
    elif a_parts[1] < b_parts[1]:
        return -1
    elif a_parts[1] > b_parts[1]:
        return 1
    elif a_parts[2] < b_parts[2]:
        return -1
    elif a_parts[2] > b_parts[2]:
        return 1

    # Compare pre-release identifiers
    a_pre = a_parts[3]
    b_pre = b_parts[3]

    # A version with a pre-release is lower than the same version without one
    if a_pre and not b_pre:
        return -1
    if b_pre and not a_pre:
        return 1

    # Compare each identifier
    for a_id, b_id in zip(a_pre, b_pre):
        # Check if identifiers are numeric
        a_is_num = a_id.isdigit()
        b_is_num = b_id.isdigit()

        if a_is_num and b_is_num:
            if int(a_id) < int(b_id):
                return -1
            elif int(a_id) > int(b_id):
                return 1
        else:
            if a_id < b_id:
                return -1
            elif a_id > b_id:
                return 1

    # If all shared identifiers are equal, the one with fewer identifiers is lower
    if len(a_pre) < len(b_pre):
        return -1
    elif len(a_pre) > len(b_pre):
        return 1

    return 0

