def evaluate(expr, variables=None):
    if not expr:
        raise ValueError("Empty expression")
    expr = expr.replace(" ", "")
    if variables is None:
        variables = {}

    def tokenize(expr):
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isdigit() or expr[i] == '.':
                j = i
                while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                    j += 1
                tokens.append(('number', expr[i:j]))
                i = j
            elif expr[i].isalpha() or expr[i] == '_':
                j = i
                while j < len(expr) and (expr[j].isalpha() or expr[j] == '_' or expr[j].isdigit()):
                    j += 1
                tokens.append(('name', expr[i:j]))
                i = j
            elif expr[i] in "+-*/^()":
                tokens.append(('operator', expr[i]))
                i += 1
            elif expr[i] == ',':
                tokens.append(('comma', ','))
                i += 1
            else:
                raise ValueError(f"Unknown character: {expr[i]}")
        return tokens

    def parse_function_call(tokens, i):
        if tokens[i][0] != 'name':
            raise ValueError("Function call expected")
        func_name = tokens[i][1]
        i += 1
        if tokens[i][0] != '(':
            raise ValueError("Missing '(' after function name")
        i += 1
        args = []
        while True:
            if tokens[i][0] == ')':
                break
            if tokens[i][0] == 'comma':
                i += 1
            args.append(parse_expression(tokens, i))
            if tokens[i][0] == ')':
                break
            if tokens[i][0] != 'comma':
                raise ValueError("Missing ',' between function arguments")
            i += 1
        if func_name == 'abs':
            if len(args) != 1:
                raise ValueError("abs requires exactly one argument")
            return ('abs', args[0])
        elif func_name in ('min', 'max'):
            if len(args) < 1:
                raise ValueError(f"{func_name} requires at least one argument")
            return (func_name, args)
        else:
            raise ValueError(f"Unknown function: {func_name}")

    def parse_expression(tokens, i):
        if tokens[i][0] == '(':
            i += 1
            expr, i = parse_expression(tokens, i)
            if tokens[i][0] != ')':
                raise ValueError("Missing closing parenthesis")
            i += 1
            return ('paren', expr), i
        elif tokens[i][0] == 'name':
            name = tokens[i][1]
            i += 1
            if i < len(tokens) and tokens[i][0] == '(':
                return parse_function_call(tokens, i - 1)
            else:
                if name not in variables:
                    raise ValueError(f"Unknown variable: {name}")
                return ('variable', name), i
        elif tokens[i][0] == 'number':
            return ('number', tokens[i][1]), i + 1
        elif tokens[i][0] == '-':
            if i + 1 < len(tokens) and (tokens[i + 1][0] in '+-*/^(' or tokens[i + 1][0] == 'number'):
                return ('unary_minus', parse_expression(tokens, i + 1)[0]), i + 2
            else:
                raise ValueError("Invalid unary minus")
        else:
            raise ValueError("Unexpected token")

    def parse_term(tokens, i):
        left, i = parse_factor(tokens, i)
        while i < len(tokens) and tokens[i][0] == '*':
            op = tokens[i][1]
            i += 1
            right, i = parse_factor(tokens, i)
            left = ('op', op, left, right)
        return left, i

    def parse_factor(tokens, i):
        left, i = parse_power(tokens, i)
        while i < len(tokens) and tokens[i][0] == '/':
            op = tokens[i][1]
            i += 1
            right, i = parse_power(tokens, i)
            left = ('op', op, left, right)
        return left, i

    def parse_power(tokens, i):
        left, i = parse_unary(tokens, i)
        while i < len(tokens) and tokens[i][0] == '^':
            op = tokens[i][1]
            i += 1
            right, i = parse_unary(tokens, i)
            left = ('op', op, left, right)
        return left, i

    def parse_unary(tokens, i):
        if i < len(tokens) and tokens[i][0] == 'unary_minus':
            op = tokens[i][0]
            i += 1
            expr, i = parse_power(tokens, i)
            return ('unary_op', op, expr), i
        else:
            return parse_expression(tokens, i)

    def evaluate_token(token):
        if token[0] == 'number':
            return float(token[1])
        elif token[0] == 'variable':
            return variables[token[1]]
        elif token[0] == 'abs':
            return abs(evaluate_token(token[1]))
        elif token[0] in ('min', 'max'):
            args = [evaluate_token(arg) for arg in token[1]]
            return min(args) if token[0] == 'min' else max(args)
        elif token[0] == 'op':
            op, left, right = token[1], token[2], token[3]
            left_val = evaluate_token(left)
            right_val = evaluate_token(right)
            if op == '+':
                return left_val + right_val
            elif op == '-':
                return left_val - right_val
            elif op == '*':
                return left_val * right_val
            elif op == '/':
                if right_val == 0:
                    raise ValueError("Division by zero")
                return left_val / right_val
            elif op == '^':
                return left_val ** right_val
            else:
                raise ValueError(f"Unknown operator: {op}")
        elif token[0] == 'unary_op':
            _, op, expr = token
            val = evaluate_token(expr)
            return -val
        else:
            raise ValueError(f"Unknown token type: {token[0]}")

    tokens = tokenize(expr)
    expr_tree, i = parse_expression(tokens, 0)
    if i != len(tokens):
        raise ValueError("Trailing garbage")
    return evaluate_token(expr_tree)

import re

def parse_ini(text):
    lines = text.split('\n')
    result = {}
    current_section = None
    current_keys = {}

    for line_number, line in enumerate(lines, 1):
        line = line.strip()
        if not line:
            continue
        if line.startswith(';') or line.startswith('#'):
            continue

        if line.startswith('[') and line.endswith(']'):
            section_name = line[1:-1].strip()
            if not section_name:
                raise ValueError(f"line {line_number}: section name is empty")
            current_section = section_name
            current_keys = {}
            result[current_section] = current_keys
        else:
            if '=' not in line:
                raise ValueError(f"line {line_number}: line does not contain '='")
            key_part, value_part = line.split('=', 1)
            key = key_part.strip()
            if not key:
                raise ValueError(f"line {line_number}: key is empty")
            value = value_part.strip()

            if value.startswith('"'):
                value = parse_quoted_value(value, line_number)
            else:
                value = parse_unquoted_value(value, line_number)

            current_keys[key] = value

    return result

def parse_quoted_value(value, line_number):
    if not value.startswith('"'):
        raise ValueError(f"line {line_number}: quoted value does not start with \"")
    value = value[1:]
    escaped = False
    result = []
    i = 0
    while i < len(value):
        if escaped:
            if value[i] == '"':
                result.append('"')
            elif value[i] == '\\':
                if i + 1 < len(value):
                    if value[i + 1] == 'n':
                        result.append('\n')
                        i += 1
                    elif value[i + 1] == 't':
                        result.append('\t')
                        i += 1
                    elif value[i + 1] == '\\':
                        result.append('\\')
                        i += 1
                    else:
                        raise ValueError(f"line {line_number}: bad escape sequence")
                else:
                    raise ValueError(f"line {line_number}: bad escape sequence")
            else:
                result.append(value[i])
            escaped = False
            i += 1
        elif value[i] == '\\':
            escaped = True
            i += 1
        elif value[i] == '"':
            i += 1
            break
        else:
            result.append(value[i])
            i += 1
    if i < len(value):
        raise ValueError(f"line {line_number}: text after closing quote")
    return ''.join(result)

def parse_unquoted_value(value, line_number):
    comment_start = -1
    for i, char in enumerate(value):
        if char in (';', '#') and (i == 0 or value[i - 1].isspace()):
            comment_start = i
            break
    if comment_start != -1:
        value = value[:comment_start].strip()
    return value

import heapq

def shortest_path(graph, src, dst):
    # Check if src or dst are not present in the graph
    nodes = set(graph.keys())
    for node in [src, dst]:
        if node not in nodes:
            # Check if node is a neighbor of any node
            is_neighbor = False
            for neighbors in graph.values():
                if node in neighbors:
                    is_neighbor = True
                    break
            if not is_neighbor:
                raise ValueError(f"Node {node} is not present in the graph.")

    # Check for non-positive weights
    for neighbors in graph.values():
        for weight in neighbors.values():
            if weight <= 0:
                raise ValueError("All weights must be greater than 0.")

    # If src == dst, return the special case
    if src == dst:
        return (0, [src])

    # Dijkstra's algorithm
    distances = {node: float('inf') for node in graph}
    distances[src] = 0
    priority_queue = [(0, src, [src])]
    visited = set()

    while priority_queue:
        current_dist, current_node, path = heapq.heappop(priority_queue)

        if current_node in visited:
            continue

        visited.add(current_node)

        if current_node == dst:
            return (current_dist, path)

        for neighbor, weight in graph[current_node].items():
            distance = current_dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor, path + [neighbor]))

    # If dst is not reachable
    return None

class OutOfStock(Exception):
    pass


class Inventory:
    def __init__(self, stock=None):
        self._stock = stock.copy() if stock is not None else {}

    def stock(self, item):
        return self._stock.get(item, 0)

    def add(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        self._stock[item] = self.stock(item) + qty

    def remove(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        current_stock = self.stock(item)
        if qty > current_stock:
            raise OutOfStock(f"Cannot remove {qty} of {item}, only {current_stock} in stock")
        self._stock[item] = current_stock - qty


def fulfil(inventory, order):
    if not order:
        return 0
    for item, qty in order.items():
        if qty <= 0:
            raise ValueError("Order quantity must be positive")
    try:
        total = 0
        for item, qty in order.items():
            inventory.remove(item, qty)
            total += qty
        return total
    except OutOfStock:
        return 0

