from collections.abc import Mapping, Sequence

def render(template, context):
    class Renderer:
        def __init__(self, template, context):
            self.template = template
            self.context = context
            self.pos = 0
            self.output = []
            self.stack = []

        def parse(self):
            while self.pos < len(self.template):
                if self.template[self.pos] == '{':
                    if self.pos + 1 < len(self.template) and self.template[self.pos + 1] == '{':
                        self.handle_variable()
                    elif self.pos + 1 < len(self.template) and self.template[self.pos + 1] == '%':
                        self.handle_tag()
                    else:
                        self.output.append('{')
                        self.pos += 1
                else:
                    self.output.append(self.template[self.pos])
                    self.pos += 1

        def handle_variable(self):
            self.pos += 2
            start = self.pos
            while self.pos < len(self.template) and self.template[self.pos] != '}':
                self.pos += 1
            if self.pos >= len(self.template):
                self.output.append(self.template[start:])
                return
            content = self.template[start:self.pos]
            self.pos += 1
            content = content.strip()
            if '|' in content:
                path_str, filter_name = content.split('|', 1)
                path = path_str.split('.')
                value = self.get_value(path)
                if value is None or value == '':
                    value = ''
                else:
                    value = str(value)
                if filter_name == 'upper':
                    self.output.append(value.upper())
                elif filter_name == 'lower':
                    self.output.append(value.lower())
                elif filter_name == 'title':
                    self.output.append(value.title())
                elif filter_name == 'length':
                    self.output.append(str(len(value)))
                else:
                    raise ValueError(f"Unknown filter: {filter_name}")
            else:
                path = content.split('.')
                value = self.get_value(path)
                if value is None or value == '':
                    self.output.append('')
                else:
                    self.output.append(str(value))

        def get_value(self, path):
            current = self.context
            for name in path:
                if isinstance(current, Mapping) and name in current:
                    current = current[name]
                elif isinstance(current, Sequence) and name.isdigit():
                    current = current[int(name)]
                else:
                    return None
            return current

        def handle_tag(self):
            self.pos += 2
            start = self.pos
            while self.pos < len(self.template) and self.template[self.pos] != '%':
                self.pos += 1
            if self.pos >= len(self.template):
                self.output.append(self.template[start:])
                return
            content = self.template[start:self.pos]
            self.pos += 1
            content = content.strip()
            if content.startswith('if'):
                self.handle_if(content)
            elif content.startswith('for'):
                self.handle_for(content)
            else:
                raise ValueError(f"Unknown tag: {content}")

        def handle_if(self, content):
            if content.startswith('if not'):
                condition = content[6:].strip()
                reverse = True
            else:
                condition = content[2:].strip()
                reverse = False
            path = condition.split('.')
            value = self.get_value(path)
            if reverse:
                if value is None or value == '':
                    self.stack.append('if')
                    self.parse()
                    self.stack.pop()
                else:
                    self.output.append('')
            else:
                if value is not None and value != '':
                    self.stack.append('if')
                    self.parse()
                    self.stack.pop()
                else:
                    self.output.append('')

        def handle_for(self, content):
            parts = content[3:].strip().split('in')
            if len(parts) != 2:
                raise ValueError(f"Invalid for tag: {content}")
            name = parts[0].strip()
            path = parts[1].strip().split('.')
            value = self.get_value(path)
            if not isinstance(value, Sequence):
                self.output.append('')
                return
            self.stack.append(('for', name, path))
            for item in value:
                self.context[name] = item
                self.parse()
            self.context.pop(name, None)
            self.stack.pop()

    renderer = Renderer(template, context)
    renderer.parse()
    return ''.join(renderer.output)
